<script setup lang="ts">
import {ref} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import {request,dateTime} from '../../api'
import {requireWorkspace,money,type Row} from '../../workspace'
const invoice=ref<Row|null>(null),identifier=ref(0),error=ref('')
onLoad((q:any)=>identifier.value=Number(q?.id||0))
onShow(async()=>{if(!await requireWorkspace())return;try{if(!identifier.value)throw Error('缺少结算编号');invoice.value=await request('/api/invoices/'+identifier.value)}catch(e:any){error.value=e.message}})
function printCopy(){
 // #ifdef H5
 window.print()
 // #endif
}
</script>
<template><WorkspaceShell title="结算单副本" back><view v-if="error" class="error">{{error}}</view><template v-if="invoice"><view class="receipt-actions"><view><text class="page-title">结算单副本</text><text class="caption">沿用原单号及当前有效版本，不重复产生收入。</text></view>
 <!-- #ifdef H5 --><button class="primary" @click="printCopy"><AppIcon name="paperplane" :size="17"/> 打印或存为PDF</button><!-- #endif -->
 </view><view class="receipt-sheet"><view class="receipt-brand"><text>{{invoice.copy_details.clinic_name}}</text><text>实际治疗结算单</text></view><view class="receipt-identifiers"><text>结算编号 {{invoice.invoice_no}}</text><text>有效版本 {{invoice.current_revision.revision_no}}</text></view><view class="receipt-person"><view><text>就诊人</text><text>{{invoice.copy_details.patient_name}}</text></view><view><text>接诊牙医</text><text>{{invoice.copy_details.dentist_name}}</text></view><view><text>实际接诊</text><text>{{dateTime(invoice.copy_details.started_at)}}</text></view><view><text>就诊编号</text><text>{{invoice.copy_details.encounter_no}}</text></view></view><view class="receipt-table-head"><text>实际治疗项目</text><text>数量</text><text>单价</text><text>金额</text></view><view v-for="line in invoice.lines" :key="line.id" class="receipt-table-line"><text>{{line.treatment_name_snapshot}}</text><text>{{Number(line.quantity_snapshot)}} {{line.unit_name_snapshot}}</text><text>{{money(line.unit_price_snapshot)}}</text><text>{{money(line.subtotal)}}</text></view><view v-if="!invoice.lines.length" class="receipt-zero">{{invoice.current_revision.zero_charge_basis}}</view><view class="receipt-total"><text>合计（人民币）</text><text>¥{{money(invoice.current_revision.total_amount)}}</text></view><view class="receipt-footer"><text>本版开具时间 {{dateTime(invoice.current_revision.issued_at)}}</text><text>{{invoice.copy_details.clinic_address}}</text><text>门店联系 {{invoice.copy_details.clinic_phone}}</text><text>如需核实或纸本协助，请提供以上结算编号及版本。费用更正保留原有历史。</text></view></view></template></WorkspaceShell></template>
<style scoped>.receipt-actions{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px}.receipt-actions>button{display:flex;align-items:center;gap:7px;font-size:13px}.receipt-sheet{max-width:920px;margin:0 auto;background:#fff;padding:48px 54px;border:1px solid #e3e8ef}.receipt-brand{display:flex;flex-direction:column;align-items:center;gap:12px}.receipt-brand>text:first-child{font-size:17px}.receipt-brand>text:last-child{font-size:26px;font-weight:600;letter-spacing:3px}.receipt-identifiers{display:flex;justify-content:space-between;gap:18px;padding:30px 0 18px;border-bottom:2px solid #253347;font-size:12px}.receipt-person{display:grid;grid-template-columns:1fr 1fr;gap:18px 24px;padding:24px 0 30px;font-size:13px}.receipt-person>view{display:flex;gap:15px;overflow-wrap:anywhere}.receipt-person>view>text:first-child{color:#758296;white-space:nowrap}.receipt-table-head,.receipt-table-line{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:12px;padding:17px 0;border-bottom:1px solid #e3e8ef;font-size:13px}.receipt-table-head{font-weight:600;background:#f2f5f8;padding:13px 10px}.receipt-table-head>text:not(:first-child),.receipt-table-line>text:not(:first-child){text-align:right}.receipt-total{display:flex;justify-content:space-between;align-items:center;padding:25px 0;border-bottom:1px solid #e3e8ef}.receipt-total>text:last-child{font-size:26px;font-weight:600}.receipt-footer{display:flex;flex-direction:column;gap:8px;font-size:11px;line-height:1.9;color:#758296;margin-top:25px}.receipt-zero{padding:25px 0;color:#758296;font-size:13px;line-height:1.9}@media(max-width:680px){.receipt-sheet{padding:28px 17px}.receipt-brand>text:first-child{font-size:14px}.receipt-brand>text:last-child{font-size:22px}.receipt-actions{flex-wrap:wrap}.receipt-actions>button{width:100%;font-size:12px}.receipt-person{grid-template-columns:1fr;font-size:12px;gap:13px;padding:23px 0}.receipt-identifiers{flex-direction:column;gap:7px;font-size:10px}.receipt-table-head,.receipt-table-line{font-size:11px;gap:8px;grid-template-columns:1.7fr 1fr 1fr 1fr}.receipt-table-head{padding:12px 6px}.receipt-total{font-size:12px}.receipt-total>text:last-child{font-size:22px}.receipt-footer{font-size:10px}}
</style>
